import { type NextRequest, NextResponse } from "next/server";
import {
  adminDatabases,
  DATABASE_ID,
  COLLECTION,
  Query,
} from "@/lib/appwrite";
import {
  NIGHT_ACCESS_COOKIE,
  getClientIp,
  nextSixAmIstMs,
  signNightAccess,
} from "@/lib/night-access";

export const dynamic = "force-dynamic";

const MAX_FAILED_ATTEMPTS = 3;

/**
 * POST /api/night-access/verify { code }
 *
 * Verifies a temporary access code (generated by the assistant) against
 * the `night_access_codes` collection. On success it sets a signed
 * `ea_night_access` bypass cookie (valid until 6am, or the code expiry,
 * whichever is sooner) so the visitor can use the site during closed
 * hours.
 *
 * Wrong codes are tracked per IP in `night_access_blocks`. On the 3rd
 * failed attempt the IP is blocked permanently (until an admin unblocks
 * it); blocked IPs get a 403 telling them to contact the admin.
 */
export async function POST(request: NextRequest) {
  let body: { code?: unknown } = {};
  try {
    body = (await request.json()) as { code?: unknown };
  } catch {
    body = {};
  }
  const code =
    typeof body.code === "string" ? body.code.trim().toUpperCase() : "";
  const ip = getClientIp(request.headers);
  const db = adminDatabases();
  const now = new Date();

  if (!code) {
    return NextResponse.json({ error: "Enter an access code." }, { status: 400 });
  }

  // Blocked IP? (permanent until an admin unblocks it.)
  try {
    const blocked = await db.listDocuments(
      DATABASE_ID,
      COLLECTION.night_access_blocks,
      [Query.equal("ip", ip), Query.equal("blocked", true), Query.limit(1)],
    );
    if (blocked.total > 0 || blocked.documents.length > 0) {
      return NextResponse.json(
        {
          error:
            "This IP is blocked after too many wrong access codes. Please contact the admin to unblock it.",
        },
        { status: 403 },
      );
    }
  } catch (err) {
    console.error("[night-access] blocklist lookup failed", err);
    // Fail open on a lookup error so a transient DB issue doesn't lock
    // everyone out; the code check below still applies.
  }

  // Look up the code.
  let codeDoc: Record<string, unknown> | null = null;
  try {
    const res = await db.listDocuments(
      DATABASE_ID,
      COLLECTION.night_access_codes,
      [Query.equal("code", code), Query.limit(1)],
    );
    if (res.documents.length > 0) {
      codeDoc = res.documents[0] as unknown as Record<string, unknown>;
    }
  } catch (err) {
    console.error("[night-access] code lookup failed", err);
    return NextResponse.json(
      { error: "Could not verify the code right now. Please try again." },
      { status: 500 },
    );
  }

  const expiresAt = codeDoc
    ? new Date(String(codeDoc.expiresAt ?? "")).getTime()
    : Number.NaN;
  const maxUses = Number(codeDoc?.maxUses ?? 1);
  const usedCount = Number(codeDoc?.usedCount ?? 0);
  const valid =
    codeDoc !== null &&
    Number.isFinite(expiresAt) &&
    expiresAt > now.getTime() &&
    usedCount < maxUses;

  if (!valid) {
    // Record a failed attempt for this IP.
    let remaining = MAX_FAILED_ATTEMPTS - 1;
    try {
      const existing = await db.listDocuments(
        DATABASE_ID,
        COLLECTION.night_access_blocks,
        [Query.equal("ip", ip), Query.limit(1)],
      );
      if (existing.documents.length > 0) {
        const doc = existing.documents[0] as unknown as Record<string, unknown>;
        const attempts = Number(doc.failedAttempts ?? 0) + 1;
        const blocked = attempts >= MAX_FAILED_ATTEMPTS;
        await db.updateDocument(
          DATABASE_ID,
          COLLECTION.night_access_blocks,
          String(doc.$id),
          {
            failedAttempts: attempts,
            blocked,
            blockedAt: blocked ? now.toISOString() : undefined,
            lastAttemptAt: now.toISOString(),
          },
        );
        remaining = Math.max(0, MAX_FAILED_ATTEMPTS - attempts);
        if (blocked) {
          return NextResponse.json(
            {
              error:
                "Wrong access code. This IP is now blocked after 3 wrong attempts. Please contact the admin to unblock it.",
            },
            { status: 403 },
          );
        }
      } else {
        await db.createDocument(
          DATABASE_ID,
          COLLECTION.night_access_blocks,
          "unique()",
          {
            ip,
            failedAttempts: 1,
            blocked: false,
            lastAttemptAt: now.toISOString(),
          },
        );
        remaining = MAX_FAILED_ATTEMPTS - 1;
      }
    } catch (err) {
      console.error("[night-access] failed-attempt recording failed", err);
    }
    return NextResponse.json(
      {
        error: `Wrong access code. ${remaining} attempt${remaining === 1 ? "" : "s"} left before this IP is blocked.`,
      },
      { status: 401 },
    );
  }

  // Valid code: consume one use and set the bypass cookie.
  // (valid === true implies codeDoc is non-null; guard for the compiler.)
  if (!codeDoc) {
    return NextResponse.json({ error: "Wrong access code." }, { status: 401 });
  }
  const codeDocId = String(codeDoc.$id);
  try {
    await db.updateDocument(
      DATABASE_ID,
      COLLECTION.night_access_codes,
      codeDocId,
      { usedCount: usedCount + 1 },
    );
  } catch (err) {
    console.error("[night-access] could not consume code use", err);
  }

  const cookieExp = Math.min(expiresAt, nextSixAmIstMs(now));
  const token = await signNightAccess(cookieExp);
  const res = NextResponse.json({ ok: true });
  res.cookies.set(NIGHT_ACCESS_COOKIE, token, {
    httpOnly: true,
    secure: true,
    sameSite: "lax",
    path: "/",
    expires: new Date(cookieExp),
  });
  return res;
}
